def babylonian_squareroot(number):
    """Write a function for computing square roots using the babylonian method."""
    if number < 0:
        raise ValueError("math domain error")
    if number == 0:
        return 0.0

    value = float(number)
    guess = value
    if guess < 1.0:
        guess = 1.0

    while True:
        next_guess = (guess + value / guess) / 2.0
        if not next_guess < guess:
            return guess
        guess = next_guess
